{
  "title": "变量与赋值练习",
  "questions": [
    {
      "form": "choice",
      "stem": "执行以下代码后，变量 y 的值是多少？\n```python\nx = 1\ny = x\nx = 2\n```",
      "options": [
        {"id": "a", "text": "1"},
        {"id": "b", "text": "2"},
        {"id": "c", "text": "未定义"},
        {"id": "d", "text": "报错"}
      ],
      "correct_option_ids": ["a"],
      "explanation": "执行 x = 1 后，x 绑定到整数 1。执行 y = x 时，y 绑定到 x 当前绑定的对象，即整数 1。之后 x = 2 重新绑定 x 到整数 2，但 y 仍然绑定到整数 1，因此 y 的值是 1。"
    }
  ]
}
